CREATE TABLE roles (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, full_name VARCHAR(140) NOT NULL, created_at TIMESTAMP(6) NOT NULL);
CREATE TABLE user_roles (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE carts (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL UNIQUE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE cart_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, cart_id BIGINT NOT NULL, product_id BIGINT NOT NULL, quantity INT NOT NULL, UNIQUE KEY uq_cart_product(cart_id,product_id), FOREIGN KEY(cart_id) REFERENCES carts(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id));
CREATE TABLE orders (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL, shipping_name VARCHAR(140) NOT NULL, shipping_address VARCHAR(300) NOT NULL, shipping_city VARCHAR(100) NOT NULL, shipping_postal_code VARCHAR(30) NOT NULL, shipping_country VARCHAR(100) NOT NULL, total DECIMAL(12,2) NOT NULL, created_at TIMESTAMP(6) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id), INDEX idx_order_user(user_id,created_at));
CREATE TABLE order_items (id BIGINT PRIMARY KEY AUTO_INCREMENT, order_id BIGINT NOT NULL, product_id BIGINT NOT NULL, product_name VARCHAR(160) NOT NULL, unit_price DECIMAL(10,2) NOT NULL, quantity INT NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(product_id) REFERENCES products(id));
INSERT INTO roles(name) VALUES ('ROLE_USER'),('ROLE_ADMIN');
